export function getTranslation(key: string, lang?: string): string {
  // Language priority: explicit arg → standalone key (written by Settings) →
  // the app settings JSON (so a language chosen before Settings mounts still
  // applies on boot) → English.
  let stored = localStorage.getItem('wanderlust_app_lang');
  if (!stored) {
    try {
      const s = JSON.parse(localStorage.getItem('wanderlust_app_settings') || '{}');
      if (s.language) stored = s.language;
    } catch {
      /* corrupted settings — fall through to English */
    }
  }
  const currentLang = (lang || stored || 'en') as AppLanguage;
  const dict = TRANSLATIONS[currentLang] || TRANSLATIONS.en;
  const viewDict = VIEW_STRINGS[currentLang] || VIEW_STRINGS.en;
  return dict[key] || viewDict[key] || VIEW_STRINGS.en[key] || TRANSLATIONS.en[key] || key;
}

/** getTranslation + {placeholder} interpolation, e.g. tv('dayN', { n: 3 }) → 'Day 3'. */
export function tv(key: string, vars: Record<string, string | number> = {}, lang?: string): string {
  let s = getTranslation(key, lang);
  for (const [k, v] of Object.entries(vars)) s = s.split(`{${k}}`).join(String(v));
  return s;
}

export function playAudioAlert() {
  try {
    const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;
    if (!AudioCtx) return;
    const ctx = new AudioCtx();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.type = 'sine';
    // Pleasant dual chime
    osc.frequency.setValueAtTime(587.33, ctx.currentTime); // D5
    osc.frequency.setValueAtTime(880, ctx.currentTime + 0.12); // A5

    gain.gain.setValueAtTime(0.15, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.4);

    osc.connect(gain);
    gain.connect(ctx.destination);

    osc.start();
    osc.stop(ctx.currentTime + 0.45);
  } catch (e) {
    console.warn('Web Audio playback error:', e);
  }
}
